-- Function: public.sp_sync_parent_guardian
-- Backup generated on 2026-10-25 20:34:06

CREATE OR REPLACE PROCEDURE public.sp_sync_parent_guardian(IN p_tenant_id uuid, IN p_child_id uuid, IN p_parent_email character varying, IN p_parent_name character varying, IN p_relationship character varying, IN p_phone character varying)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_norm_email VARCHAR;     v_trimmed_email VARCHAR;     v_user_id UUID;     v_role_id UUID;     v_person_id UUID;     v_first_name VARCHAR;     v_last_name VARCHAR;     v_rel VARCHAR;     v_name_parts TEXT[]; BEGIN     IF p_parent_email IS NULL OR TRIM(p_parent_email) = '' THEN         RETURN;     END IF;      v_trimmed_email := TRIM(p_parent_email);     v_norm_email := UPPER(v_trimmed_email);     v_rel := COALESCE(NULLIF(TRIM(p_relationship), ''), 'Parent');      -- Split name into first and last     v_name_parts := regexp_split_to_array(COALESCE(NULLIF(TRIM(p_parent_name), ''), 'Parent Guardian'), '\s+');     v_first_name := v_name_parts[1];     IF array_length(v_name_parts, 1) > 1 THEN         v_last_name := array_to_string(v_name_parts[2:], ' ');     ELSE         v_last_name := 'Guardian';     END IF;      -- 1. Find or create User     SELECT id INTO v_user_id FROM users WHERE normalized_email = v_norm_email LIMIT 1;     IF v_user_id IS NULL THEN         v_user_id := gen_random_uuid();         INSERT INTO users (             id, tenant_id, email, normalized_email, email_confirmed, first_name, last_name, display_name, password_hash, security_stamp, is_active, created_at, updated_at         ) VALUES (             v_user_id, p_tenant_id, v_trimmed_email, v_norm_email, TRUE, v_first_name, v_last_name,             COALESCE(NULLIF(TRIM(p_parent_name), ''), v_first_name || ' ' || v_last_name),             '', md5(random()::text), TRUE, NOW(), NOW()         ) ON CONFLICT (normalized_email) DO NOTHING;          SELECT id INTO v_user_id FROM users WHERE normalized_email = v_norm_email LIMIT 1;          SELECT id INTO v_role_id FROM roles WHERE name = 'Parent' AND (tenant_id = p_tenant_id OR tenant_id IS NULL) LIMIT 1;         IF v_role_id IS NOT NULL THEN             INSERT INTO user_roles (user_id, role_id) VALUES (v_user_id, v_role_id) ON CONFLICT DO NOTHING;         END IF;     END IF;      -- 2. Find or create Person     SELECT id INTO v_person_id FROM persons WHERE tenant_id = p_tenant_id AND user_id = v_user_id LIMIT 1;     IF v_person_id IS NULL THEN         v_person_id := gen_random_uuid();         INSERT INTO persons (             id, tenant_id, user_id, first_name, last_name, relationship, email, mobile_phone, has_portal_access, receives_daily_updates, receives_photos, created_at, updated_at         ) VALUES (             v_person_id, p_tenant_id, v_user_id, v_first_name, v_last_name, v_rel, v_trimmed_email, NULLIF(TRIM(p_phone), ''), TRUE, TRUE, TRUE, NOW(), NOW()         );     ELSE         IF p_phone IS NOT NULL AND TRIM(p_phone) <> '' THEN             UPDATE persons SET mobile_phone = TRIM(p_phone), updated_at = NOW() WHERE id = v_person_id;         END IF;     END IF;      -- 3. Link child_guardians     INSERT INTO child_guardians (         id, tenant_id, child_id, person_id, relationship, is_primary, has_legal_custody, can_pickup, can_receive_information, can_authorize_medical_care     ) VALUES (         gen_random_uuid(), p_tenant_id, p_child_id, v_person_id, v_rel, TRUE, TRUE, TRUE, TRUE, TRUE     ) ON CONFLICT (child_id, person_id) DO UPDATE SET          relationship = EXCLUDED.relationship,          can_pickup = TRUE;      -- 4. Link family_relationships     INSERT INTO family_relationships (         id, tenant_id, child_id, user_id, relationship, is_primary, created_at, status, verified_at     ) VALUES (         gen_random_uuid(), p_tenant_id, p_child_id, v_user_id, v_rel, TRUE, NOW(), 'Verified', NOW()     ) ON CONFLICT (child_id, user_id) DO UPDATE SET          relationship = EXCLUDED.relationship,         status = 'Verified',         revoked_at = NULL,         verified_at = NOW();      -- 5. Link authorized_pickups     INSERT INTO authorized_pickups (         id, tenant_id, child_id, person_id, relationship, is_active, notes     ) VALUES (         gen_random_uuid(), p_tenant_id, p_child_id, v_person_id, v_rel, TRUE, 'Primary guardian on file.'     ) ON CONFLICT DO NOTHING; END; $procedure$ ;
